from pydantic import BaseModel, ConfigDict, model_validator

# The set of placement group strategies supported by Ray. Mirrors
# ``ray.util.placement_group.VALID_PLACEMENT_GROUP_STRATEGIES`` but is declared
# locally to keep this module free of heavier Ray core imports.
PlacementStrategy = Literal["PACK", "SPREAD", "STRICT_PACK", "STRICT_SPREAD"]


class BundleConfig(BaseModel):
    """A validated resource bundle used for placement.

    ``CPU`` and ``GPU`` are always present (defaulting to ``0.0``). Any
    additional keyword arguments are treated as named resources (e.g. ``TPU``)
    and stored as floats. All resource values must be non-negative numbers.
    """

    model_config = ConfigDict(extra="allow")

    CPU: float = 0.0
    GPU: float = 0.0

    @model_validator(mode="before")
    @classmethod
    def _coerce_and_validate_resources(cls, data):
        if not isinstance(data, dict):
            return data

        validated = {}
        for key, value in data.items():
            # ``bool`` is a subclass of ``int``, but it is not a meaningful
            # resource quantity, so reject it explicitly.
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    f"Resource '{key}' must be a number, got {value!r}."
                )
            value = float(value)
            if value < 0:
                raise ValueError(
                    f"Resource '{key}' must be non-negative, got {value}."
                )
            validated[key] = value
        return validated


class PlacementGroupConfig(BaseModel):
    """A validated placement group configuration.

    Exactly one of ``bundles`` (an explicit list of bundles) or
    ``bundle_per_worker`` (a single bundle replicated per worker) must be
    provided. ``strategy`` must be one of the supported placement strategies.
    """

    model_config = ConfigDict(extra="forbid")

    bundles: Optional[List[BundleConfig]] = None
    bundle_per_worker: Optional[BundleConfig] = None
    strategy: PlacementStrategy

    @model_validator(mode="after")
    def _validate_exactly_one_bundle_source(self) -> "PlacementGroupConfig":
        has_bundles = self.bundles is not None
        has_bundle_per_worker = self.bundle_per_worker is not None

        if has_bundles and has_bundle_per_worker:
            raise ValueError(
                "Cannot specify both 'bundles' and 'bundle_per_worker'."
            )
        if not has_bundles and not has_bundle_per_worker:
            raise ValueError(
                "Must specify either 'bundle_per_worker' or 'bundles'."
            )
        return self

    def model_dump(self, **kwargs):
        data = super().model_dump(**kwargs)
        # Only surface the bundle source that was actually provided.
        if self.bundles is None:
            data.pop("bundles", None)
        if self.bundle_per_worker is None:
            data.pop("bundle_per_worker", None)
        return data
